package dev.studyforge.banking.adapter.inmemory; import dev.studyforge.banking.application.*; import java.util.concurrent.locks.*; public final class InMemoryUnitOfWork implements UnitOfWork{private final InMemoryAccountRepository accounts;private final InMemoryTransactionRepository transactions;private final ReentrantLock lock=new ReentrantLock(); public InMemoryUnitOfWork(InMemoryAccountRepository a,InMemoryTransactionRepository t){accounts=a;transactions=t;} public <T>T execute(Work<T> work){lock.lock();try{InMemoryAccountRepository a=new InMemoryAccountRepository();a.replace(accounts.copy());InMemoryTransactionRepository t=new InMemoryTransactionRepository();t.replace(transactions.copy());T result=work.apply(a,t);accounts.replace(a.copy());transactions.replace(t.copy());return result;}finally{lock.unlock();}}}
